    M = draw(st.integers(2, 6))
    sets = []
    for _ in range(N):
        A = draw(st.integers(1, M))
        elems = draw(st.lists(st.integers(1, M), min_size=A, max_size=A, unique=True))
        sets.append(elems)
    lines = [f"{N} {M}"]
    for s in sets:
        lines.append(str(len(s)))
        lines.append(" ".join(map(str, s)))
    return "\n".join(lines) + "\n"


