    t = inp.split()
    pos = 0
    N = int(t[pos]); pos += 1
    M = int(t[pos]); pos += 1
    if not (1 <= N <= 2 * 10**5 and 2 <= M <= 2 * 10**5):
        return False
    total = 0
    for _ in range(N):
        if pos >= len(t):
            return False
        A = int(t[pos]); pos += 1
        if A < 0:
            return False
        total += A
        if pos + A > len(t):
            return False
        elems = [int(x) for x in t[pos:pos + A]]
        pos += A
        if len(set(elems)) != len(elems):
            return False
        if any(e < 1 or e > M for e in elems):
            return False
    if pos != len(t):
        return False
    return 1 <= total <= 5 * 10**5


def ref(inp):
