    pos = 0
    N = int(t[pos]); pos += 1
    M = int(t[pos]); pos += 1
    sets = []
    for _ in range(N):
        A = int(t[pos]); pos += 1
        sets.append(set(int(x) for x in t[pos:pos + A]))
        pos += A
    # Minimum k such that some k sets form a connected group (intersection graph)
    # whose union contains 1 and M. Answer is k-1.
    for k in range(1, N + 1):
        for combo in combinations(range(N), k):
            union = set()
            for i in combo:
                union |= sets[i]
            if 1 not in union or M not in union:
                continue
            # connectivity check via intersection graph
            seen = {combo[0]}
            stack = [combo[0]]
            while stack:
                u = stack.pop()
                for v in combo:
                    if v not in seen and sets[u] & sets[v]:
                        seen.add(v)
                        stack.append(v)
            if len(seen) == k:
                return str(k - 1)
    return "-1"
