def _parse(inp):
    t = inp.split()
    pos = 0
    N = int(t[pos]); pos += 1
    M = int(t[pos]); pos += 1
    sets = []
    for _ in range(N):
        a = int(t[pos]); pos += 1
        if a < 0:
            raise ValueError
        s = [int(x) for x in t[pos:pos + a]]
        if len(s) != a:
            raise ValueError
        pos += a
        sets.append(s)
    if pos != len(t):
        raise ValueError
    return N, M, sets


def validate(inp):
    try:
        N, M, sets = _parse(inp)
    except (ValueError, IndexError):
        return False
    if not (1 <= N <= 2 * 10**5 and 2 <= M <= 2 * 10**5):
        return False
    total = sum(len(s) for s in sets)
    if not (1 <= total <= 5 * 10**5):
        return False
    for s in sets:
        if len(set(s)) != len(s):
            return False
        if any(not (1 <= x <= M) for x in s):
            return False
    return True


